$manifest = Get-Content -Raw -LiteralPath 'crates/convert/tests/fixtures/starcoder-conversion/pretrained-reference.json' | ConvertFrom-Json
if ($manifest.model -cne 'bigcode/tiny_starcoder_py' -or $manifest.revision -cnotmatch '^[0-9a-f]{40}$') {
  throw 'Expected the immutable official tiny StarCoder checkpoint manifest'
}
$profile = if ($env:RUNNER_OS -eq 'Windows') {
  $manifest.profiles.windows
} elseif ($env:RUNNER_OS -eq 'Linux') {
  $manifest.profiles.linux
} else {
  throw "Unsupported native reference profile: $env:RUNNER_OS"
}
$files = @($profile.inputs)
if ($files.Count -ne 9) { throw 'Expected all nine pinned tiny StarCoder input files' }
foreach ($file in $files) {
  $destination = Join-Path $env:LLAMA_TEST_STARCODER_HF $file.path
  $url = "https://huggingface.co/$($manifest.model)/resolve/$($manifest.revision)/$($file.path)"
  # Redirect bodies can exceed tiny sidecars; final length and hash remain exact.
  $maximumTransferBytes = [Math]::Max([long]$file.bytes, [long]1048576)
  & curl --fail --location --ipv4 --retry 3 --max-time 900 --max-filesize $maximumTransferBytes --create-dirs --output $destination $url
  if ($LASTEXITCODE -ne 0) { throw "Download failed: tiny StarCoder/$($file.path)" }
  if ((Get-Item -LiteralPath $destination).Length -ne $file.bytes) {
    throw "Length mismatch: tiny StarCoder/$($file.path)"
  }
  $hash = (Get-FileHash -LiteralPath $destination -Algorithm SHA256).Hash.ToLowerInvariant()
  if ($hash -cne $file.sha256) { throw "SHA-256 mismatch: tiny StarCoder/$($file.path)" }
  Write-Host "Verified tiny StarCoder/$($file.path): $($file.bytes) bytes, SHA-256 $hash"
}
